'       1 AS SEQ,',
'       8 AS PAGE_NUMBER',
'  FROM MOBASHER_TASKS',
' WHERE DEPARTMENT_ID = :P_DEPT_ID',
'UNION ALL',
unistr('SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0647\0627\0645\064A: '', '' My Tasks: '') || COUNT(t.ID) AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0645\0647\0627\0645\064A'', ''My Tasks'') AS TITLE,'),
'       ''tasks'' AS ICON,',
'       ''departments'' AS TYPE,',
'       2 AS SEQ,',
'       11 AS PAGE_NUMBER',
'  FROM MOBASHER_TASKS t, MOBASHER_TASK_ASSIGNED_EMPLOYEE e',
' WHERE t.ID = e.TASK_ID',
'   AND e.EMPLOYEE_ID = :P_EMP_ID',
'UNION ALL',
unistr('SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0627\0644\0645\0647\0627\0645 \0627\0644\0645\0646\062C\0632\0629: '', '' Completed Tasks: '') || COUNT(t.ID) AS COUNT,'),
unistr('       DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0645\0647\0627\0645 \0627\0644\0645\0646\062C\0632\0629'', '' Completed Tasks '') AS TITLE,'),
'       ''check'' AS ICON,',
'       ''employees'' AS TYPE,',
'       3 AS SEQ,',
'       11 AS PAGE_NUMBER',
