unistr('-- SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0647\0627\0645 \062C\0627\0631\064A \0627\0644\0639\0645\0644 \0639\0644\064A\0647\0627: '', '' Inprogress Tasks: '') || COUNT(t.ID) AS COUNT,'),
