unistr('-- SELECT DECODE(NVL(:P_LANG, ''ar''), ''ar'', '' \0645\0647\0627\0645 \0627\0644\0642\0633\0645: '', '' Department Tasks: '') || COUNT(t.ID) AS COUNT,'),
unistr('--        DECODE(NVL(:P_LANG, ''ar''), ''ar'', ''\0645\0647\0627\0645 \0627\0644\0642\0633\0645'', ''Department Tasks'') AS TITLE,'),
