'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        NUMBER;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'    v_body      	    VARCHAR2(32000);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P1_UPLOAD,',
'                        p_sep => '':'' );',
'',
'    SELECT *',
'      INTO l_file',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE NAME = :P1_UPLOAD;',
'',
'    l_result := SYSTEM_INTEGRATION.UPLOAD_AWS ( p_file => l_file.BLOB_CONTENT);',
'',
'    UPDATE EMP SET CLOB = l_result WHERE EMPNO = 8040;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0645\0631\0641\0642!'');'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(58027783672210762)
,p_internal_uid=>41800702754089421
);
