wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(93801098877202228)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload File'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P3_ATTACHEMENT,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count > 1 THEN                    ',
'        FOR i IN 1 .. l_file_names.count LOOP',
'            SELECT *',
'              INTO l_file',
'              FROM APEX_APPLICATION_TEMP_FILES',
'             WHERE NAME = l_file_names(i);',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                                || DBMS_RANDOM.STRING(''x'', 8)',
'                                || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'            l_request_url := :G_OCI_BASE_URL||''/b/tasks_mangement/o/''||l_file_name;',
'',
'            l_result := APEX_WEB_SERVICE.make_rest_request (',
'                            p_url                  => l_request_url,',
'                            p_http_method          => ''PUT'',',
'                            p_body_blob            => l_file.BLOB_CONTENT,',
'                            p_credential_static_id => ''OCI_AUTH''',
'                        );',
'',
'            IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'                SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                             p_process_name  => ''OCI_OS.put_object_P3 - App: '' || :APP_ID,',
'                                             p_error_code    => -2,',
'                                             p_error_message => SUBSTR(l_result, 1, 4000),',
'                                             p_logger_name   => :APP_USER',
'                                        );',
'                RAISE_APPLICATION_ERROR(-20002, ''Error with uploading Data!'');',
'            END IF;',
'',
'            INSERT INTO MOBASHER_TASK_ATTACHEMENTS ( TASK_ID, URL, FILE_NAME, MIME_TYPE, IS_ACTIVE )',
'                VALUES ( :P3_ID, l_request_url, l_file.FILENAME, l_file.MIME_TYPE, 1 );',
'            ',
'            IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0645\0631\0641\0642!'');'),
'            END IF;',
'        END LOOP;',
'    ELSIF l_file_names.count = 1 THEN',
'        SELECT *',
'          INTO l_file',
'          FROM APEX_APPLICATION_TEMP_FILES',
'         WHERE NAME = :P3_ATTACHEMENT;',
'',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'        l_request_url := :G_OCI_BASE_URL||''/b/tasks_mangement/o/''||l_file_name;',
'        ',
'        l_result := APEX_WEB_SERVICE.make_rest_request (',
'                        p_url                  => l_request_url,',
'                        p_http_method          => ''PUT'',',
'                        p_body_blob            => l_file.BLOB_CONTENT,',
'                        p_credential_static_id => ''OCI_AUTH''',
'                    );',
'',
'        IF APEX_WEB_SERVICE.g_status_code NOT IN ( 200, 201, 202, 203, 204, 205, 206, 207, 226 ) THEN',
'            SYSTEM_CONTROLS.ERROR_LOGS ( p_error_type    => ''SYSTEM_ERROR'',',
'                                             p_process_name  => ''OCI_OS.put_object_P10 - App: '' || :APP_ID,',
'                                             p_error_code    => -2,',
'                                             p_error_message => SUBSTR(l_result, 1, 4000),',
'                                             p_logger_name   => :APP_USER',
'                                        );',
'            RAISE_APPLICATION_ERROR(-20004, ''Error with uploading Data!'');',
'        END IF;',
'',
'        INSERT INTO MOBASHER_TASK_ATTACHEMENTS ( TASK_ID, URL, FILE_NAME, MIME_TYPE, IS_ACTIVE )',
'                VALUES ( :P3_ID, l_request_url, l_file.FILENAME, l_file.MIME_TYPE, 1 );',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0645\0631\0641\0642!'');'),
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P3_ATTACHEMENT'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>37070897028318736
);
