wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(94576109370152993)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CREATE ASSIGEN EMPLOYEES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_employees  APEX_T_VARCHAR2;',
'BEGIN',
'    l_employees := APEX_STRING.SPLIT (',
'                        p_str => :P9_EMPLOYEE_ID,',
'                        p_sep => '':'' );',
'',
'    DELETE FROM MOBASHER_TASK_ASSIGNED_EMPLOYEE WHERE TASK_ID = :P9_ID;',
'    ',
'    IF l_employees.count > 1 THEN',
'        FOR i IN 1 .. l_employees.count LOOP',
'            INSERT INTO MOBASHER_TASK_ASSIGNED_EMPLOYEE ( TASK_ID, DEPARTMENT_ID, EMPLOYEE_ID )',
'                VALUES ( :P9_ID, :P_DEPT_ID, l_employees(i) );',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0625\0636\0627\0641\0629 \0627\0644\0645\0648\0638\0641\064A\0646 \0639\0644\0649 \0627\0644\0645\0647\0645\0629!'');'),
'            END IF;',
'        END LOOP;',
'    ELSIF l_employees.count = 1 THEN',
'        INSERT INTO MOBASHER_TASK_ASSIGNED_EMPLOYEE ( TASK_ID, DEPARTMENT_ID, EMPLOYEE_ID )',
'                VALUES ( :P9_ID, :P_DEPT_ID, :P9_EMPLOYEE_ID );',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \0625\0636\0627\0641\0629 \0627\0644\0645\0648\0638\0641 \0639\0644\0649 \0627\0644\0645\0647\0645\0629!'');'),
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(94401431607501605)
,p_internal_uid=>37845907521269501
);
